"""Distro and how-to guides. Each: (slug, title, meta description, html body)."""
def _distro(slug, name, pid, blurb, good, tips):
    def f(lk):
        L = lk(pid, name)
        return (f"how-to-install-{slug}-from-usb", f"How to install {name} from a USB drive",
          f"Step-by-step guide to installing {name} from a bootable USB drive, with preparation tips, what to expect and fixes for common problems.",
          f"""<p>{blurb}</p>
<h2>What you need</h2><ul><li>A bootable USB drive with {L}.</li><li>A backup of your files.</li><li>A computer that can <a href="guide-how-to-boot-from-usb.html">boot from USB</a>.</li></ul>
<h2>Installation steps</h2><ol><li>Insert the drive and open the <a href="guide-boot-menu-keys-by-brand.html">boot menu</a>.</li><li>Choose the USB drive (the UEFI entry on newer computers).</li><li>Try {name} in live mode, or start the installer straight away.</li><li>Select language, keyboard layout and network.</li><li>Choose whether to erase the disk or <a href="guide-how-to-dual-boot-linux-and-windows.html">dual boot with Windows</a>.</li><li>Create your user account, finish the install and remove the drive when asked.</li></ol>
<h2>Why people choose {name}</h2><ul>{"".join(f"<li>{g}</li>" for g in good)}</ul>
<h2>Tips</h2><ul>{"".join(f"<li>{t}</li>" for t in tips)}</ul>
<p>More help: <a href="guide-how-to-fix-a-usb-drive-that-will-not-boot.html">USB not booting?</a> and <a href="faq.html">Help and FAQ</a>.</p>""")
    return f
_D = [
 ("ubuntu","Ubuntu","800016537860","Ubuntu is one of the most popular Linux systems in the world, known for a polished desktop and a huge support community.",["Large community and thousands of tutorials.","Regular security updates, with LTS releases for stability.","Wide hardware support."],["Choose an LTS release for fewer changes.","Enable third-party drivers during setup if offered."]),
 ("linux-mint","Linux Mint","800016421272","Linux Mint offers a traditional desktop that Windows users find familiar, built on Ubuntu.",["Familiar menu and taskbar layout.","Media codecs ready to use.","Runs well on modest hardware."],["Cinnamon is the main edition; Xfce suits older machines.","Use the Update Manager after install."]),
 ("zorin-os","Zorin OS","800034663198","Zorin OS is designed to feel familiar to people moving from Windows or macOS.",["Layout switcher mimics other systems.","Clean, modern look.","Good for first-time Linux users."],["Check graphics settings after install.","Explore the built-in software store."]),
 ("debian","Debian","800016323704","Debian is a long-established, very stable system that many other distributions are built on.",["Exceptional stability.","Huge software archive.","Ideal for servers and long-lived desktops."],["Pick the desktop environment you like during install.","Stable releases favour reliability over the newest software."]),
 ("fedora","Fedora","800016354792","Fedora brings newer software and technology, and is popular with developers.",["Up-to-date kernel and tools.","Strong security defaults.","Clean GNOME desktop."],["Releases are supported for around 13 months, so plan upgrades.","Enable third-party repositories for extra codecs if you want them."]),
]
_G = [
("how-to-dual-boot-ubuntu-and-windows","How to dual boot Ubuntu and Windows safely","Prepare Windows, shrink the partition and install Ubuntu beside it with a boot menu to choose either system at start-up.",
 "<p>Ubuntu and Windows can share one computer. At start-up you pick which to use.</p><h2>Prepare</h2><ul><li>Full backup first.</li><li>Turn off Windows Fast Startup.</li><li>Suspend BitLocker and keep the recovery key.</li><li>Shrink the Windows partition in Disk Management to free 40 GB or more.</li></ul><h2>Install</h2><ol><li><a href=\"guide-how-to-boot-from-usb.html\">Boot from the Ubuntu USB</a>.</li><li>Choose Install Ubuntu, then Install alongside Windows.</li><li>Set the size split and continue.</li></ol><h2>Afterwards</h2><p>A GRUB menu appears at every start-up. See the general <a href=\"guide-how-to-dual-boot-linux-and-windows.html\">dual boot guide</a>.</p>"),
("linux-for-students","Best Linux for students","Which Linux systems suit students: easy installs, office software, coding tools and low hardware needs.",
 "<p>Students need reliability, office tools and a low budget for hardware. Linux handles all three.</p><h2>What to look for</h2><ul><li>Simple installation and updates.</li><li>LibreOffice for documents, with Word and PowerPoint file support.</li><li>Programming tools for computing courses.</li></ul><h2>Good picks</h2><p>Ubuntu, Linux Mint and Zorin OS suit most students. See <a href=\"guide-best-linux-for-beginners.html\">best Linux for beginners</a> and <a href=\"guide-best-linux-for-old-laptops.html\">old laptops</a>.</p><h2>Check your course</h2><p>Confirm any required software has a Linux version or web alternative before switching.</p>"),
("linux-for-seniors-and-first-time-users","Linux for first-time computer users","A gentle introduction to Linux for people who want a simple, secure computer without complicated setup.",
 "<p>Linux can be a calm, simple choice for browsing, email, video calls and photos.</p><h2>Why it suits simple use</h2><ul><li>Few pop-ups and clear update prompts.</li><li>Strong security habits built in.</li><li>Works on older machines.</li></ul><h2>How to start</h2><ol><li>Try it with a <a href=\"guide-how-to-try-linux-without-installing.html\">live USB</a>.</li><li>Choose a friendly system like Linux Mint or Zorin OS.</li><li>Ask a family member to help with the first install.</li></ol>"),
("linux-for-business-and-small-office","Linux for small business computers","Using Linux in a small office: cost of hardware, security, office software and what to check before switching.",
 "<p>Many small offices run Linux for browsing, accounting in the browser, email and documents.</p><h2>Benefits</h2><ul><li>Extends the life of older PCs.</li><li>Reduces exposure to common malware.</li><li>Easy to set up identical machines from one USB drive.</li></ul><h2>Check first</h2><ul><li>Specialist software with no Linux version.</li><li>Printer and scanner support.</li><li>Staff training time.</li></ul><p>Trial with a <a href=\"guide-how-to-try-linux-without-installing.html\">live USB</a> before rolling out.</p>"),
("how-to-use-a-live-usb-for-computer-repair","Using a Linux USB to repair a computer","Boot a Linux USB to rescue files, check disks, reset passwords and fix start-up problems when Windows will not load.",
 "<p>A rescue USB works even when the installed system will not start.</p><h2>What it can do</h2><ul><li>Copy your files to an external drive. See <a href=\"guide-recover-files-with-a-linux-usb.html\">recover files</a>.</li><li>Check disk health and repair file systems.</li><li>Test RAM and hardware.</li><li>Back up a whole disk with <a href=\"guide-how-to-clone-a-disk-with-clonezilla.html\">Clonezilla</a>.</li></ul><h2>Steps</h2><ol><li>Boot from the USB.</li><li>Open the file manager and find your internal drive.</li><li>Copy files to another drive before attempting repairs.</li></ol>"),
("how-to-partition-a-disk-for-linux","How to partition a disk for Linux","Partitioning basics for a Linux install: root, swap, home and EFI partitions explained simply.",
 "<p>Most installers partition automatically. Understanding the pieces helps if you choose manual setup.</p><h2>Common partitions</h2><ul><li><strong>EFI:</strong> about 512 MB, holds boot files on UEFI computers.</li><li><strong>Root (/):</strong> the system, 30 GB or more.</li><li><strong>Home:</strong> your files, optional separate partition.</li><li><strong>Swap:</strong> overflow memory, a few GB, or a swap file.</li></ul><h2>Safety</h2><p>Back up first and double-check the target disk. Never format a partition you have not identified. See <a href=\"guide-how-to-install-linux-from-usb.html\">install Linux</a>.</p>"),
("how-to-encrypt-your-linux-install","How to encrypt your Linux disk","Turn on full disk encryption during Linux installation to protect your files if a laptop is lost or stolen.",
 "<p>Full disk encryption scrambles everything on the drive unless the right passphrase is entered at start-up.</p><h2>How</h2><ol><li>During install choose the encryption option (often LUKS).</li><li>Create a strong passphrase you will remember.</li><li>Store a written recovery note somewhere safe.</li></ol><h2>Things to know</h2><ul><li>Forgetting the passphrase means losing the data.</li><li>Performance impact is small on modern computers.</li></ul><p>Related: <a href=\"guide-best-linux-for-privacy-and-security.html\">privacy and security</a>.</p>"),
("how-to-set-up-wifi-and-drivers-on-linux","Wi-Fi, graphics and driver setup on Linux","Fix Wi-Fi and install graphics drivers on Linux after installation, including NVIDIA and AMD tips.",
 "<p>Most hardware works at once. A few devices need extra drivers.</p><h2>Wi-Fi</h2><ul><li>Use the network icon to connect.</li><li>If no Wi-Fi appears, check the Additional Drivers tool or connect by cable and update.</li></ul><h2>Graphics</h2><ul><li>Open Additional Drivers or the system's driver tool for NVIDIA options.</li><li>AMD and Intel graphics usually work without extra steps.</li></ul><h2>Tip</h2><p>Test hardware first with a <a href=\"guide-how-to-check-your-pc-works-with-linux.html\">live USB</a>.</p>"),
("linux-gaming-with-steam-and-proton","Gaming on Linux with Steam and Proton","How Steam Play and Proton let you play many Windows games on Linux, with tips on drivers and compatibility.",
 "<p>Steam's Proton layer runs many Windows games on Linux with little effort.</p><h2>Getting started</h2><ol><li>Install Steam from the software store.</li><li>Enable Steam Play for all titles in Settings.</li><li>Install current graphics drivers.</li></ol><h2>Check compatibility</h2><p>Look up a game's rating on ProtonDB before buying. Some online games with anti-cheat do not run.</p><p>See <a href=\"guide-best-linux-for-gaming.html\">best Linux for gaming</a>.</p>"),
("how-to-run-windows-programs-on-linux","How to run Windows programs on Linux","Options for running Windows software on Linux: Wine, Proton, virtual machines and web alternatives.",
 "<p>Several routes let Windows programs run on Linux.</p><ul><li><strong>Wine:</strong> runs many Windows apps directly.</li><li><strong>Proton:</strong> built for games through Steam.</li><li><strong>Virtual machine:</strong> runs a full copy of Windows inside Linux.</li><li><strong>Web apps:</strong> many tools now work in a browser.</li></ul><h2>Advice</h2><p>Look for a native Linux alternative first, then try Wine. See <a href=\"guide-linux-vs-windows-which-is-right-for-you.html\">Linux vs Windows</a>.</p>"),
("what-is-gnome-kde-xfce-cinnamon","GNOME, KDE, Xfce and Cinnamon compared","A simple comparison of the main Linux desktop environments to help you choose a look and feel.",
 "<p>The desktop environment controls menus, windows and settings.</p><ul><li><strong>GNOME:</strong> clean and modern, uses an overview instead of a classic menu.</li><li><strong>KDE Plasma:</strong> very customisable, familiar to Windows users.</li><li><strong>Xfce:</strong> light and quick, good for older computers.</li><li><strong>Cinnamon:</strong> traditional layout, used by Linux Mint.</li><li><strong>LXQt and LXDE:</strong> the lightest options.</li></ul><p>Try them in live mode. Read <a href=\"guide-what-is-a-linux-distribution.html\">what is a distribution</a>.</p>"),
("how-to-use-the-linux-terminal-basics","Linux terminal basics for beginners","Ten essential terminal commands for new Linux users, explained in plain language.",
 "<p>You rarely need the terminal on a beginner system, but a few commands are handy.</p><ul><li><code>pwd</code> shows where you are.</li><li><code>ls</code> lists files.</li><li><code>cd folder</code> moves into a folder.</li><li><code>cp</code> and <code>mv</code> copy and move files.</li><li><code>mkdir</code> makes a folder.</li><li><code>sudo</code> runs a command as administrator.</li><li><code>apt update</code> and <code>apt upgrade</code> update Debian-based systems.</li><li><code>man command</code> shows the manual.</li></ul><p>Be careful with commands you do not understand, especially <code>sudo</code>.</p>"),
("how-to-use-ventoy-multiboot-usb","Using Ventoy to carry many systems on one USB","How Ventoy lets one USB drive hold many operating system images and pick one at start-up.",
 "<p>Ventoy turns a USB drive into a multi-system boot menu. Copy ISO files onto it and choose at start-up.</p><h2>Basics</h2><ol><li>Install Ventoy to the drive once.</li><li>Copy ISO files like normal files.</li><li>Boot and pick the system from the menu.</li></ol><h2>Notes</h2><ul><li>Larger drives hold more systems.</li><li>Some images need special handling; check Ventoy's compatibility list.</li></ul><p>See <a href=\"guide-what-is-ventoy.html\">what is Ventoy</a>.</p>"),
("how-to-reset-a-forgotten-windows-password-safely","Locked out of your computer? Safe options","Legitimate ways to regain access to your own computer and files when you have forgotten a password.",
 "<p>If you are locked out of a computer you own, start with official recovery.</p><ul><li>Use your Microsoft account password reset online.</li><li>Check for a recovery key saved to your account.</li><li>If all else fails, boot a Linux USB to copy your files off before reinstalling. See <a href=\"guide-recover-files-with-a-linux-usb.html\">recover files</a>.</li></ul><p>Only use these steps on computers you own.</p>"),
("how-to-clean-install-vs-upgrade","Clean install or upgrade: which is better?","Compare a clean install with an in-place upgrade for Linux and decide which suits your computer.",
 "<p>A clean install starts fresh. An upgrade keeps your files and apps.</p><h2>Clean install</h2><ul><li>Removes old clutter and problems.</li><li>Needs a backup and a bootable USB.</li></ul><h2>Upgrade</h2><ul><li>Quicker and keeps settings.</li><li>Can carry old problems forward.</li></ul><p>For a very old release, a clean install from a new <a href=\"guide-how-to-create-a-bootable-usb-drive.html\">bootable USB</a> is usually safest.</p>"),
("how-to-use-linux-on-a-chromebook-or-old-tablet","Giving an old PC or Chromebook new life","Ideas for reusing ageing hardware with lightweight Linux, from home servers to media centres.",
 "<p>Old computers still do plenty with the right software.</p><ul><li>Lightweight Linux for daily browsing.</li><li>A home media centre or retro games machine.</li><li>A file server or print server.</li><li>A learning machine for kids.</li></ul><p>Start with <a href=\"guide-best-linux-for-old-laptops.html\">best Linux for old laptops</a>.</p>"),
("how-to-make-a-linux-home-server","Turn a spare PC into a home server","Basic ideas for running a simple file, media or backup server on Linux with an old computer.",
 "<p>A spare PC can store files, stream media and back up your devices.</p><h2>Steps</h2><ol><li>Install a stable system such as Debian or Ubuntu Server.</li><li>Give it a fixed address on your network.</li><li>Share folders with Samba.</li><li>Add automatic backups.</li></ol><p>Keep it updated and protect it with a strong password.</p>"),
("how-to-pick-the-right-usb-drive-size","How much storage do you need on a USB drive?","Choosing USB drive and SD card capacity for live Linux, persistence, installers and rescue tools.",
 "<p>Most Linux systems need 4 to 8 GB for the image itself.</p><ul><li>Install-only use: a standard capacity is plenty.</li><li>Live use with persistence: choose extra space for files and apps.</li><li>Multi-system drives: more capacity holds more images.</li></ul><p>See <a href=\"guide-usb-3-vs-usb-2-for-live-linux.html\">USB 3 vs USB 2</a>.</p>"),
("how-to-safely-eject-and-store-your-usb","Looking after your bootable USB drive","Simple care tips to keep a bootable USB drive working for years.",
 "<p>A little care keeps a drive reliable.</p><ul><li>Eject before unplugging when using it in an installed system.</li><li>Keep it away from heat, water and magnets.</li><li>Avoid saving files to a drive you rely on for booting.</li><li>Keep a spare for emergencies.</li></ul>"),
]
def more(lk):
    return [f(lk) for f in [_distro(*d) for d in _D]] + [(a,b,c,d) for a,b,c,d in _G]
